"""Every rounding rule of meterbill lives here.

Decimal rounding is done on integers, so the result never depends on the
decimal context (precision, rounding mode or traps) of the running thread.
"""

from __future__ import annotations

import math
from decimal import Decimal, InvalidOperation

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _check_method(method) -> None:
    if not isinstance(method, str) or method not in _METHODS:
        raise ValueError(f"unknown rounding method: {method!r}")


def _make(sign: int, coefficient: int, exponent: int) -> Decimal:
    """The exact decimal sign * coefficient * 10**exponent."""
    return Decimal((sign, tuple(int(c) for c in str(coefficient)), exponent))


def _parts(value: Decimal):
    sign, digits, exponent = value.as_tuple()
    return sign, int("".join(map(str, digits)) or "0"), exponent


def _add(a: Decimal, b: Decimal) -> Decimal:
    """Exact a + b with the exponent of the finer operand; a zero sum is
    negative only when both operands are negative zeros (as Decimal does)."""
    sa, ca, ea = _parts(a)
    sb, cb, eb = _parts(b)
    e = min(ea, eb)
    total = (-1) ** sa * ca * 10 ** (ea - e) + (-1) ** sb * cb * 10 ** (eb - e)
    if total == 0:
        return _make(1 if (sa and sb) else 0, 0, e)
    return _make(1 if total < 0 else 0, abs(total), e)


def _negate(a: Decimal) -> Decimal:
    return a.copy_negate()


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    """The multiple of `step` nearest to `value`; `method` decides ties and direction."""
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    _check_method(method)
    if not step.is_finite() or not step > 0:
        raise ValueError("step must be a positive decimal")
    if value.is_nan():
        if value.is_snan():
            raise InvalidOperation("signaling NaN")
        return value
    if value.is_infinite():
        raise InvalidOperation("cannot round an infinity")
    vsign, vcoef, vexp = _parts(value)
    _, scoef, sexp = _parts(step)
    common = min(vexp, sexp)
    numerator = vcoef * 10 ** (vexp - common)
    denominator = scoef * 10 ** (sexp - common)
    count, rest = divmod(numerator, denominator)
    if method != DOWN:
        twice = 2 * rest
        if twice > denominator:
            count += 1
        elif twice == denominator:
            if method == HALF_UP or count % 2 == 1:
                count += 1
    return _make(vsign, count * scoef, sexp)


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    """One part per amount, each a multiple of `step`, adding up to the
    rounded sum.

    Each amount is cut toward zero to the step; what the cuts lost against
    the half-up rounded sum goes on the last amount that is not zero.
    """
    parts = [round_amount(a, step, DOWN) for a in amounts]
    whole = Decimal(0)
    for a in amounts:
        whole = _add(whole, a)
    whole = round_amount(whole, step, HALF_UP)
    cut = _make(0, 0, step.as_tuple().exponent)
    for p in parts:
        cut = _add(cut, p)
    rest = _add(whole, _negate(cut))
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] = _add(parts[i], rest)
            break
    return parts


def legacy_cents(value: float, places: int = 2) -> float:
    """A float amount as the old customer system settled it (binary floating point)."""
    if isinstance(places, bool) or not isinstance(places, int) or not 0 <= places <= 6:
        raise ValueError("places must be an integer from 0 to 6")
    scale = 10**places
    return math.floor(value * scale + 0.5) / scale


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    """`value` written with `places` digits after the point, rounded by `method`."""
    if isinstance(places, bool) or not isinstance(places, int) or places < 0:
        raise ValueError("places must be a non-negative integer")
    if isinstance(value, float):
        if not isinstance(method, str) or method != HALF_EVEN:
            raise ValueError("a float can only be written half to even")
        return format(value, f".{places}f")
    if not isinstance(value, Decimal):
        raise TypeError("value must be a float or a Decimal")
    rounded = round_amount(value, _make(0, 1, -places), method)
    return format(rounded, "f")

"""The payable amount: some currencies settle in coins coarser than the cent."""

from __future__ import annotations

from decimal import Decimal

from meterbill import money


def payable(total: Decimal, rule: str) -> Decimal:
    """`rule` is the currency's `cash` entry in the tariff book."""
    if rule == "none":
        return total
    if rule == "whole":
        whole = money.round_amount(total, Decimal("1"), money.HALF_EVEN)
        # Decimal(round(total)) never carried a sign on zero.
        return whole.copy_abs() if whole.is_zero() else whole
    return money.round_amount(total, Decimal(rule), money.HALF_UP)

"""Value added tax on a bill's subtotal."""

from __future__ import annotations

from decimal import Decimal

from meterbill import money


def vat(subtotal: Decimal, rate: Decimal) -> Decimal:
    # Tax offices round half to even; this is the one amount that does not round half up.
    return money.round_amount(subtotal * rate, money.CENT, money.HALF_EVEN)


def rate_label(rate: Decimal, *, method: str = money.HALF_UP) -> str:
    """`VAT 21%`; a rate with a fraction of a percent is shown to the nearest percent."""
    return f"VAT {money.fixed(rate * 100, 0, method)}%"

"""Credits from the old customer system, which stores them as binary floats."""

from __future__ import annotations

from decimal import Decimal

from meterbill import money


def settle(amount: float) -> float:
    """A credit as the old system settled it, to the cent."""
    return money.legacy_cents(amount)


def total(credits) -> Decimal:
    s = 0.0
    for c in credits:
        s += settle(c.amount)
    return Decimal(money.fixed(s, 2))


def line(credit) -> str:
    return money.fixed(settle(credit.amount), 2)

